use std::fs;
#[derive(Debug)]struct Mount{id:u32,parent:u32,root:String,path:String,kind:String,source:String,options:String}
fn unescape(value:&str)->String{value.replace("\\040"," ").replace("\\011","\t").replace("\\012","\n").replace("\\134","\\")}
fn parse(text:&str)->Vec<Mount>{text.lines().filter_map(|line|{let(a,b)=line.split_once(" - ")?;let left:Vec<_>=a.split_whitespace().collect();let right:Vec<_>=b.split_whitespace().collect();if left.len()<6||right.len()<3{return None}Some(Mount{id:left[0].parse().ok()?,parent:left[1].parse().ok()?,root:unescape(left[3]),path:unescape(left[4]),options:left[5].into(),kind:right[0].into(),source:unescape(right[1])})}).collect()}
fn main()->Result<(),Box<dyn std::error::Error>>{let args:Vec<_>=std::env::args().skip(1).collect();if args.iter().any(|s|s=="--help"){println!("mount-explorer [PATH_SUBSTRING]\nRead-only /proc/self/mountinfo snapshot, IDs and parents.");return Ok(())}if !cfg!(target_os="linux"){return Err("Linux mountinfo required".into())}if args.len()>1{return Err("At most one path filter".into())}let filter=args.first().map(String::as_str).unwrap_or("");for m in parse(&fs::read_to_string("/proc/self/mountinfo")?).iter().filter(|m|m.path.contains(filter)){println!("{} <- {}  {}  type={} source={} root={} options={}",m.id,m.parent,m.path.escape_default(),m.kind,m.source.escape_default(),m.root.escape_default(),m.options);}Ok(())}
#[cfg(test)]mod tests{use super::*;#[test]fn mountinfo_and_escapes(){let m=parse("31 20 8:1 / /my\\040disk rw,relatime shared:1 - ext4 /dev/sda1 rw\n");assert_eq!(m.len(),1);assert_eq!(m[0].path,"/my disk");assert_eq!(m[0].parent,20);assert_eq!(m[0].kind,"ext4");assert!(parse("bad").is_empty());}}
